begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(17);
select ok(exists(select 1 from pg_extension where extname='btree_gist'),'real PostgreSQL has btree_gist');
select ok(exists(select 1 from pg_constraint where conrelid='private.scheduling_occupancy'::regclass and contype='x'),'occupancy has real exclusion constraint');
select is((select enabled from private.scheduling_settings where clinic_id='71000000-0000-4000-8000-000000000001'),false,'synthetic fixture disabled by default');
select ok(not has_table_privilege('authenticated','private.scheduling_holds','INSERT'),'client cannot insert private holds');
select ok(not has_function_privilege('anon','public.scheduling_create_hold(uuid,uuid,jsonb,uuid)','EXECUTE'),'anonymous cannot execute holds');
insert into auth.users(id) values('73000000-0000-4000-8000-000000000001');
insert into public.clinic_memberships(clinic_id,user_id,role,active) values('71000000-0000-4000-8000-000000000001','73000000-0000-4000-8000-000000000001','reception',true);
select set_config('request.jwt.claim.sub','73000000-0000-4000-8000-000000000001',true);
select set_config('request.method','POST',true);
set local role authenticated;
select throws_ok($$select public.scheduling_resources('71000000-0000-4000-8000-000000000001')$$,'PT503','scheduling_disabled','DB switch is independently authoritative');
reset role;
update private.scheduling_settings set enabled=true where clinic_id='71000000-0000-4000-8000-000000000001';
select set_config('test.hold_body',jsonb_build_object('provider_resource_id','72000000-0000-4000-8000-000000000001','chair_resource_id','72000000-0000-4000-8000-000000000003','starts_at',private.scheduling_time(clock_timestamp()+interval '1 day'),'ends_at',private.scheduling_time(clock_timestamp()+interval '1 day 30 minutes'),'display_timezone','Africa/Casablanca')::text,true);
set local role authenticated;
select is(jsonb_array_length(public.scheduling_resources('71000000-0000-4000-8000-000000000001')->'items'),4,'authorized synthetic resources');
select set_config('request.method','GET',true);
select throws_ok($$select public.scheduling_resources('71000000-0000-4000-8000-000000000001')$$,'22023','invalid_request','direct RPC requires POST');
select set_config('request.method','POST',true);
select set_config('test.receipt',public.scheduling_create_hold('71000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000001',current_setting('test.hold_body')::jsonb,'75000000-0000-4000-8000-000000000001')::text,true);
select is(current_setting('test.receipt')::jsonb->'item'->>'status','held','atomic hold created');
select is(public.scheduling_create_hold('71000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000001',current_setting('test.hold_body')::jsonb,'75000000-0000-4000-8000-000000000002')->>'replayed','true','same key replays');
select throws_ok($$select public.scheduling_create_hold('71000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000002',current_setting('test.hold_body')::jsonb||'{"chair_resource_id":"72000000-0000-4000-8000-000000000004"}'::jsonb,'75000000-0000-4000-8000-000000000001')$$,'SH409','resource_conflict','provider collision rolls back paired occupancy');
select throws_ok($$select public.scheduling_create_hold('71000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000003',current_setting('test.hold_body')::jsonb||'{"provider_resource_id":"72000000-0000-4000-8000-000000000002"}'::jsonb,'75000000-0000-4000-8000-000000000001')$$,'SH409','resource_conflict','chair collision rolls back paired occupancy');
reset role;
select is((select count(*)::integer from private.scheduling_occupancy where clinic_id='71000000-0000-4000-8000-000000000001'),2,'one occupancy pair survives conflicts');
select is((select count(*)::integer from private.outbox_events where clinic_id='71000000-0000-4000-8000-000000000001'),1,'one created event despite replay and conflicts');
set local role authenticated;
select is(public.scheduling_release_hold('71000000-0000-4000-8000-000000000001',(current_setting('test.receipt')::jsonb->'item'->>'id')::uuid,'74000000-0000-4000-8000-000000000004','75000000-0000-4000-8000-000000000001')->>'transitioned','true','release transitions once');
select is(public.scheduling_release_hold('71000000-0000-4000-8000-000000000001',(current_setting('test.receipt')::jsonb->'item'->>'id')::uuid,'74000000-0000-4000-8000-000000000005','75000000-0000-4000-8000-000000000001')->>'transitioned','false','fresh key on released hold is state-idempotent');
select throws_ok($$select public.scheduling_release_hold('71000000-0000-4000-8000-000000000001','76000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000004','75000000-0000-4000-8000-000000000001')$$,'SH410','idempotency_conflict','release key bound to target');
reset role;
select * from finish();
rollback;
